import numpy as np
from scipy.optimize import curve_fit
raw=open('/workspace/graphene.dat').read().split()
x=np.array([float(s.replace(',','.')) for s in raw[0::2]])
y=np.array([float(s.replace(',','.')) for s in raw[1::2]])
nu=1e7/x
# sort ascending nu for convenience
o=np.argsort(nu); nu=nu[o]; y=y[o]; x=x[o]

def lor(x,x0,g,A,off):
    return off + A*g*g/((x-x0)**2+g*g)
def gauss(x,x0,s,A,off):
    return off + A*np.exp(-0.5*((x-x0)/s)**2)
def pvoigt(x,x0,g,A,off,eta):
    return off + A*(eta*g*g/((x-x0)**2+g*g)+(1-eta)*np.exp(-0.5*((x-x0)/(g/np.sqrt(2*np.log(2))))**2))

for name,c0 in [("G",1566),("2D",2670)]:
    print("=====",name)
    for dom,xx in [("nu",nu),("file",x)]:
        if dom=="nu":
            lo,hi=c0-250,c0+250
            m=(xx>lo)&(xx<hi)
        else:
            c=1e7/c0
            lo,hi=c-800,c+800
            m=(xx>lo)&(xx<hi)
        X=xx[m]; Y=y[m]
        # initial
        x0g = c0 if dom=="nu" else 1e7/c0
        gg = 30 if dom=="nu" else 100
        p0=[x0g,gg,Y.max()-np.median(Y),np.median(Y)]
        try:
            popt,pcov=curve_fit(lor,X,Y,p0=p0,maxfev=100000)
            pred=lor(X,*popt)
            rmse=np.sqrt(np.mean((Y-pred)**2))
            ss=1-np.sum((Y-pred)**2)/np.sum((Y-Y.mean())**2)
            print(dom,"Lorentz", "n",m.sum(),"x0=%.5g g=%.5g A=%.5g off=%.5g rmse=%.3f R2=%.4f"%(popt[0],popt[1],popt[2],popt[3],rmse,ss))
        except Exception as e: print(dom,"lor fail",e)
        try:
            p0=[x0g,gg,Y.max()-np.median(Y),np.median(Y)]
            popt,pcov=curve_fit(gauss,X,Y,p0=p0,maxfev=100000)
            pred=gauss(X,*popt)
            rmse=np.sqrt(np.mean((Y-pred)**2)); ss=1-np.sum((Y-pred)**2)/np.sum((Y-Y.mean())**2)
            print(dom,"Gauss   ", "x0=%.5g sig=%.5g A=%.5g off=%.5g rmse=%.3f R2=%.4f"%(popt[0],popt[1],popt[2],popt[3],rmse,ss))
        except Exception as e: print(dom,"gauss fail",e)
