import numpy as np
from scipy.optimize import least_squares
raw=open('/workspace/graphene.dat').read().split()
x=np.array([float(s.replace(',','.')) for s in raw[0::2]])
y=np.array([float(s.replace(',','.')) for s in raw[1::2]])
nu=1e7/x
o=np.argsort(nu); nu=nu[o]; y=y[o]

def lor(p,X):
    x0,g,A,off=p[:4]
    return off + A*g*g/((X-x0)**2+g*g)
def lorlin(p,X):
    x0,g,A,off,slope=p
    return off + slope*(X-x0) + A*g*g/((X-x0)**2+g*g)

def fit(lo,hi,model,p0,loss='soft_l1'):
    m=(nu>=lo)&(nu<=hi); X=nu[m]; Y=y[m]
    res=least_squares(lambda p: model(p,X)-Y, p0, loss=loss, f_scale=300, max_nfev=200000)
    pred=model(res.x,X)
    rmse=np.sqrt(np.mean((Y-pred)**2))
    ss=1-np.sum((Y-pred)**2)/np.sum((Y-Y.mean())**2)
    return res.x,rmse,ss,m.sum()

for name,cent in [("G",1580),("2D",2670)]:
    print("="*20,name)
    wins = [(cent-120,cent+120),(cent-80,cent+80),(cent-60,cent+60),(cent-40,cent+40),(cent-150,cent+150),(cent-200,cent+200)]
    for lo,hi in wins:
        p0=[cent,20,y[(nu>lo)&(nu<hi)].max()-np.median(y[(nu>lo)&(nu<hi)]),np.median(y[(nu>lo)&(nu<hi)])]
        try:
            p,r,s,n=fit(lo,hi,lor,p0)
            print(f"L  [{lo},{hi}] n={n:4d} x0={p[0]:8.3f} g={p[1]:7.3f} A={p[2]:9.1f} off={p[3]:9.1f} rmse={r:7.1f} R2={s:.4f}")
        except Exception as e: print("err",e)
        p0=[cent,20,y[(nu>lo)&(nu<hi)].max()-np.median(y[(nu>lo)&(nu<hi)]),np.median(y[(nu>lo)&(nu<hi)]),0]
        try:
            p,r,s,n=fit(lo,hi,lorlin,p0)
            print(f"LL [{lo},{hi}] n={n:4d} x0={p[0]:8.3f} g={p[1]:7.3f} A={p[2]:9.1f} off={p[3]:9.1f} slope={p[4]:7.2f} rmse={r:7.1f} R2={s:.4f}")
        except Exception as e: print("err",e)
